class Solution:
    def minOperations(self, nums: list[int], x: int, y: int) -> int:
        def check(ops):
            budget = ops
            for num in nums:
                need = num - ops * y
                if need > 0:
                    budget -= (need + (x - y) - 1) // (x - y)
            return budget >= 0
        lo, hi = 0, max(nums) // y + 1
        while lo < hi:
            mid = (lo + hi) // 2
            if check(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

