class Solution:
    def maxIncreasingCells(self, mat: list[list[int]]) -> int:
        from collections import defaultdict
        m, n = len(mat), len(mat[0])
        cells = defaultdict(list)
        for i in range(m):
            for j in range(n):
                cells[mat[i][j]].append((i, j))
        row_max = [0] * m
        col_max = [0] * n
        result = 0
        for val in sorted(cells.keys()):
            updates = []
            for i, j in cells[val]:
                cur = max(row_max[i], col_max[j]) + 1
                updates.append((i, j, cur))
