        return result

import heapq
class Solution:
    def shortestPathWithHops(self, n: int, edges: list[list[int]], s: int, d: int, k: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        dist = [[float('inf')] * (k + 1) for _ in range(n)]
        dist[s][0] = 0
        pq = [(0, s, 0)]
        while pq:
            d_cur, u, hops = heapq.heappop(pq)
            if d_cur > dist[u][hops]:
                continue
            if u == d:
                return d_cur
            for v, w in graph[u]:
                if d_cur + w < dist[v][hops]:
                    dist[v][hops] = d_cur + w
                    heapq.heappush(pq, (d_cur + w, v, hops))
                if hops < k and d_cur < dist[v][hops + 1]:
                    dist[v][hops + 1] = d_cur
                    heapq.heappush(pq, (d_cur, v, hops + 1))
        return min(dist[d])

