def set_interval(fn, args, t):
    cancelled = threading.Event()
    def run():
        while not cancelled.is_set():
            fn(*args)
            cancelled.wait(t / 1000)
    thread = threading.Thread(target=run, daemon=True)
    thread.start()
    return cancelled.set

