class Solution:
    def maximumSumQueries(self, nums1: list[int], nums2: list[int], queries: list[list[int]]) -> list[int]:
        n = len(nums1)
        pairs = sorted(zip(nums1, nums2), key=lambda x: -x[0])
        q_sorted = sorted(range(len(queries)), key=lambda i: -queries[i][0])
        ans = [-1] * len(queries)
        stack = []  # monotonic stack of (y, x+y), y increasing, x+y decreasing
        j = 0
        for qi in q_sorted:
            xi, yi = queries[qi]
            while j < n and pairs[j][0] >= xi:
                x, y = pairs[j]
                s = x + y
                while stack and stack[-1][1] <= s:
                    stack.pop()
                if not stack or y > stack[-1][0]:
                    stack.append((y, s))
                j += 1
            idx = bisect_left(stack, (yi,))
            if idx < len(stack):
                ans[qi] = stack[idx][1]
        return ans

