class Solution:
    def specialPerm(self, nums: list[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 1
        for mask in range(1, 1 << n):
            for last in range(n):
                if not (mask >> last & 1) or dp[mask][last] == 0:
                    continue
                for nxt in range(n):
                    if mask >> nxt & 1:
                        continue
                    if nums[nxt] % nums[last] == 0 or nums[last] % nums[nxt] == 0:
                        dp[mask | (1 << nxt)][nxt] = (dp[mask | (1 << nxt)][nxt] + dp[mask][last]) % MOD
        full = (1 << n) - 1
        return sum(dp[full]) % MOD

