class Solution:
    def minimizeConcatenatedLength(self, words: list[str]) -> int:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i, first, last):
            if i == len(words):
                return 0
            w = words[i]
            wf, wl = w[0], w[-1]
            wlen = len(w)
            # Append word to end
            save1 = 1 if last == wf else 0
            r1 = wlen - save1 + dp(i + 1, first, wl)
            # Prepend word to front
            save2 = 1 if wl == first else 0
            r2 = wlen - save2 + dp(i + 1, wf, last)
            return min(r1, r2)
        return len(words[0]) + dp(1, words[0][0], words[0][-1])

