class Solution:
    def survivedRobotsHealths(self, positions: list[int], healths: list[int], directions: str) -> list[int]:
        n = len(positions)
        indices = sorted(range(n), key=lambda i: positions[i])
        stack = []
        result = [0] * n
        for i in indices:
            if directions[i] == 'R':
                stack.append(i)
            else:
                while stack and healths[i] > 0:
                    top = stack[-1]
                    if healths[top] < healths[i]:
                        stack.pop()
                        healths[i] -= 1
                    elif healths[top] > healths[i]:
                        healths[top] -= 1
                        healths[i] = 0
                    else:
                        stack.pop()
                        healths[i] = 0
                if healths[i] > 0:
                    result[i] = healths[i]
        for i in stack:
            result[i] = healths[i]
        return [result[i] for i in range(n) if result[i] > 0]

